118	    protected boolean hasCompatibleMateNearby(Class<? extends Animal> species) {
119	        for (Location loc : getField().adjacentLocations(getLocation())) {
120	            Object organism = getField().getObjectAt(loc);
121	            if (species.isInstance(organism)) {
122	                Animal mate = (Animal) organism;
123	                if (mate.isAlive() && mate.isMale() != isMale()) {
124	                    return true;
