135	     * @param handler A predicate that decides whether the object should be accepted.
136	     * @param <T> The concrete adjacent object type.
137	     * @return The matching location, or null if none matched.
138	     */
139	    protected <T> Location findAdjacentObject(Class<T> targetType, Predicate<? super T> handler) {
140	        for (Location loc : getField().adjacentLocations(getLocation())) {
141	            Object organism = getField().getObjectAt(loc);
142	            if (targetType.isInstance(organism)) {
143	                T target = targetType.cast(organism);
144	                if (handler.test(target)) {
145	                    return loc;
146	                }
147	            }
148	        }
149	        return null;
150	    }
